// Gerador idêntico ao núcleo da v3. Sem IA, sem escrita no Airbnb.
// Executa uma vez para o JSON inteiro recebido por Webhook.
/**
 * Comparação determinística entre Descrição e A sua propriedade do Airbnb.
 * Apenas prepara propostas. Não toca no navegador nem publica conteúdo.
 * Usa como fonte o backup de cada alojamento nos 4 idiomas, sem IA.
 */

const IDIOMAS = Object.freeze(['pt', 'en', 'es', 'fr']);
const SECCOES = Object.freeze([
  'descricao', 'propriedade', 'acesso', 'comunicacao', 'outras_informacoes'
]);

function normalizarParaComparar(s) {
  return String(s)
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/&nbsp;|\u00a0/gi, ' ')
    .replace(/\r\n?/g, '\n')
    .normalize('NFC')
    .replace(/\s+/g, ' ')
    .trim();
}

function erro(status, motivo, extra = {}) {
  return { estado: status, motivo, podePropor: false, ...extra };
}

/**
 * Nunca apaga automaticamente a introdução só porque uma parte é repetida.
 * Uma introdução com informação adicional requer aprovação do idioma.
 */
function analisarIntroducao(descricao, propriedade) {
  if (typeof descricao !== 'string' || typeof propriedade !== 'string') {
    return erro('bloqueado_tipo_invalido', 'Ambos os campos precisam ser texto.');
  }
  // Comparar o primeiro parágrafo de cada secção, não a Descrição inteira.
  // Alguns anúncios têm um segundo parágrafo também em Descrição; ele deve
  // ser preservado, mas não pode bloquear a remoção da introdução duplicada.
  const primeiroDelimitadorDescricao = /<br\s*\/?>|\r?\n[ \t]*\r?\n/i.exec(descricao);
  const primeiroParagrafoDescricao = primeiroDelimitadorDescricao
    ? descricao.slice(0, primeiroDelimitadorDescricao.index)
    : descricao;
  const curta = normalizarParaComparar(primeiroParagrafoDescricao);
  if (curta.length < 80) {
    return erro('bloqueado_descricao_curta', 'Primeiro parágrafo da Descrição com menos de 80 caracteres.');
  }
  // Encontrar o PRIMEIRO delimitador de parágrafo, sem escolher um posterior.
  const delimitadores = [/<br\s*\/?>/gi, /\r?\n[ \t]*\r?\n/g];
  const encontrados = delimitadores.flatMap(rx => [...propriedade.matchAll(rx)]);
  encontrados.sort((a, b) => a.index - b.index);
  const limite = encontrados[0];
  if (!limite) return erro('bloqueado_sem_delimitador', 'Não foi encontrado <br> nem linha em branco delimitando o primeiro parágrafo.');
  const introducao = propriedade.slice(0, limite.index);
  const introducaoNormalizada = normalizarParaComparar(introducao);
  if (!introducaoNormalizada.startsWith(curta)) {
    return erro('bloqueado_sem_repeticao', 'Primeiro parágrafo da Descrição não coincide com o início da Propriedade.');
  }
  // Não aceitar correspondências que cortam uma palavra ao meio.
  const seguinte = introducaoNormalizada[curta.length] || '';
  if (seguinte && !/\s|[.,;:!?]/u.test(seguinte)) {
    return erro('bloqueado_meia_palavra', 'A coincidência termina a meio de uma palavra.');
  }
  const exclusivo = introducaoNormalizada.slice(curta.length).trim();
  const inicioResto = limite.index + limite[0].length;
  const resto = propriedade.slice(inicioResto).replace(/^(?:\s|<br\s*\/?>)*/i, '');
  if (!resto.trim() || !propriedade.endsWith(resto)) {
    return erro('bloqueado_sufixo_invalido', 'Remoção deixaria o campo vazio ou não preservaria o sufixo literal.');
  }
  return {
    estado: exclusivo ? 'aguarda_aprovacao_trecho_exclusivo' : 'repeticao_exata',
    motivo: exclusivo
      ? 'Primeiro parágrafo começa pela Descrição, mas contém frases adicionais não repetidas.'
      : 'Primeiro parágrafo da Propriedade repete o primeiro parágrafo da Descrição.',
    podePropor: true,
    percentualIntroducaoRepetido: Number((curta.length / introducaoNormalizada.length * 100).toFixed(1)),
    caracteresIntroducaoRemovida: propriedade.length - resto.length,
    introducaoRemovida: introducao,
    trechoExclusivoDaIntroducao: exclusivo,
    inicioProposto: resto.slice(0, 140),
    finalPreservadoLiteralmente: true,
    // Mantemos como sugestão para inspeção, mesmo quando ainda não aprovada.
    candidato: resto
  };
}

function validarBackup(backup) {
  if (!backup || backup.origem !== 'airbnb' || !/^\d+$/.test(String(backup.listingId || ''))) {
    throw new Error('Backup inválido: esperado origem=airbnb e listingId numérico.');
  }
  for (const secao of SECCOES) {
    if (!backup.seccoes?.[secao] || typeof backup.seccoes[secao] !== 'object') {
      throw new Error(`Backup incompleto: falta a secção ${secao}.`);
    }
    for (const lang of IDIOMAS) {
      if (typeof backup.seccoes[secao][lang] !== 'string') {
        throw new Error(`Backup incompleto: falta ${secao}/${lang} (vazio é válido, ausente não).`);
      }
    }
  }
}

function prepararMultilingue(backup, {aprovados = [], propertyId = undefined, esperadoListingId = undefined} = {}) {
  validarBackup(backup);
  const listingId = String(backup.listingId);
  if (esperadoListingId && String(esperadoListingId) !== listingId) {
    throw new Error(`ID incompatível: esperava ${esperadoListingId}, mas o backup é ${listingId}.`);
  }
  const ok = new Set(aprovados);
  for (const lang of ok) if (!IDIOMAS.includes(lang)) throw new Error(`Idioma não suportado: ${lang}`);
  const proposta = {
    schemaVersion: 1,
    listingId,
    ...(propertyId ? { propertyId: String(propertyId) } : {}),
    origem: 'proposta_para_revisao',
    dataCriacao: new Date().toISOString(),
    revisaoObrigatoria: true,
    publicacaoPermitida: false,
    seccoes: {},
    analiseDuplicacao: {},
    avisos: [
      'Não publica nem guarda conteúdo no Airbnb.',
      'Toda remoção de introdução com conteúdo exclusivo precisa de aprovação explícita por idioma.',
      'Verificar cada texto após o Autofill, antes de guardar manualmente no Airbnb.',
      'Não são criadas traduções, nem alteradas secções de acesso, comunicação e outras informações.'
    ]
  };
  for (const secao of SECCOES) {
    proposta.seccoes[secao] = {};
    for (const idioma of IDIOMAS) {
      const original = backup.seccoes[secao][idioma];
      proposta.seccoes[secao][idioma] = {
        original,
        proposto: original,
        alteracao: false,
        estado: 'preservado',
        origem: 'airbnb_original'
      };
    }
  }
  const relatorio = {
    listingId,
    idiomas: {},
    aviso: 'Revisar os trechos exclusivos da introdução ANTES de autorizar a sua remoção.'
  };
  for (const idioma of IDIOMAS) {
    const desc = backup.seccoes.descricao[idioma];
    const prop = backup.seccoes.propriedade[idioma];
    const analise = analisarIntroducao(desc, prop);
    // `candidato` contém o texto completo e fica disponível apenas na análise;
    // o valor proposto NÃO muda enquanto houver informação exclusiva sem aprovação.
    const { candidato, ...detalhes } = analise;
    const aprovado = ok.has(idioma);
    if (aprovado && !analise.podePropor) {
      throw new Error(`${idioma}: aprovação pedida, mas análise bloqueada: ${analise.motivo}`);
    }
    let aplicar = false;
    if (analise.podePropor && (!analise.trechoExclusivoDaIntroducao || aprovado)) {
      aplicar = true;
      proposta.seccoes.propriedade[idioma] = {
        original: prop,
        proposto: candidato,
        alteracao: prop !== candidato,
        estado: 'proposta_requer_revisao',
        origem: 'airbnb_original_comparado_com_descricao'
      };
    }
    proposta.analiseDuplicacao[idioma] = {
      ...detalhes,
      aprovacaoRemocaoTrechoExclusivo: aprovado,
      alteracaoIncluida: aplicar
    };
    relatorio.idiomas[idioma] = {
      estado: detalhes.estado,
      coincidencia: Boolean(analise.podePropor),
      percentualIntroducaoRepetido: detalhes.percentualIntroducaoRepetido ?? null,
      caracteresAntes: prop.length,
      caracteresDepois: aplicar ? candidato.length : prop.length,
      trechoExclusivoDaIntroducao: detalhes.trechoExclusivoDaIntroducao ?? '',
      aprovacaoRemocaoTrechoExclusivo: aprovado,
      alteracaoIncluida: aplicar,
      inicioProposto: detalhes.inicioProposto || '',
      finalPreservadoLiteralmente: detalhes.finalPreservadoLiteralmente === true
    };
  }
  return {proposta, relatorio};
}

const pedido = $input.first()?.json;
const backup = pedido?.body ?? pedido;
if (!backup || typeof backup !== 'object' || Array.isArray(backup)) {
  throw new Error('Webhook sem JSON de captura Airbnb.');
}
// Números grandes devem ser strings para não perder algarismos.
if (typeof backup.listingId !== 'string' || !/^\d+$/.test(backup.listingId)) {
  throw new Error('listingId deve ser uma string numérica.');
}
if (JSON.stringify(backup).length > 1000000) {
  throw new Error('Captura demasiado grande para este piloto (limite 1 MB).');
}
const {proposta, relatorio} = prepararMultilingue(backup, {aprovados: []});
const rows = IDIOMAS.map(idioma => ({idioma, ...relatorio.idiomas[idioma]}));
const markdown = [
  `# Airbnb ${proposta.listingId} — análise automática`,
  '',
  'PENDENTE DE REVISÃO. Nenhuma publicação foi efetuada.',
  '',
  '| Idioma | Repetição confirmada | Antes → Proposto | Estado |',
  '|---|---|---|---|',
  ...rows.map(r => `| ${r.idioma.toUpperCase()} | ${r.coincidencia ? 'Sim' : 'Não'} | ${r.caracteresAntes} → ${r.caracteresDepois} | ${r.estado} |`),
  '',
  '## Trechos exclusivos do primeiro parágrafo',
  '',
  ...rows.flatMap(r => [`### ${r.idioma.toUpperCase()}`, r.trechoExclusivoDaIntroducao || '(nenhum)', '']),
  '## Próxima ação',
  'Ler os trechos exclusivos; aprovar somente os idiomas revistos com a CLI v3.',
  'As 5 secções e os 4 idiomas originais permanecem disponíveis no JSON de entrada arquivado.',
  'Não aprovar, preencher ou guardar automaticamente.',
  ''
].join('\n');
return [{json: {
  ok: true,
  schemaVersion: 1,
  listingId: proposta.listingId,
  status: rows.some(x => x.estado === 'aguarda_aprovacao_trecho_exclusivo') ? 'REVISAO_NECESSARIA' : 'ANALISE_PRONTA',
  proposta,
  diferencas: relatorio,
  relatorioMarkdown: markdown
}}];
